package com.codegym.controller;
import com.codegym.model.Customer; import com.codegym.service.CustomerService; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet("/customers") public class CustomerServlet extends HttpServlet { private final CustomerService service=new CustomerService(); protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String a=r.getParameter("action");if(a==null)a="list";if("delete".equals(a)){service.delete(Integer.parseInt(r.getParameter("id")));s.sendRedirect("customers");return;}if("create".equals(a)){r.getRequestDispatcher("/customer/form.jsp").forward(r,s);return;}if("edit".equals(a)||"view".equals(a)){Customer c=service.find(Integer.parseInt(r.getParameter("id")));if(c==null){s.sendError(404);return;}r.setAttribute("customer",c);r.getRequestDispatcher("view".equals(a)?"/customer/view.jsp":"/customer/form.jsp").forward(r,s);return;}r.setAttribute("customers",service.findAll());r.getRequestDispatcher("/customer/list.jsp").forward(r,s);} protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{r.setCharacterEncoding("UTF-8");String id=r.getParameter("id");service.save(new Customer(id==null||id.isBlank()?0:Integer.parseInt(id),r.getParameter("name"),r.getParameter("email"),r.getParameter("address")));s.sendRedirect("customers");}}
